css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader::before { content: ''; position: absolute; left: 50%; top: 50%; width: 16%; height: 16%; margin: -8% 0 0 -8%; border-radius: 50%; background: var(--accent); box-shadow: 0 0 calc(var(--loader-size) * .14) var(--accent); }
.loader span { position: absolute; left: 8%; right: 8%; top: 35%; bottom: 35%; border: calc(var(--loader-size) * .025) solid color-mix(in srgb, var(--accent-2) 40%, transparent); border-radius: 50%; }
.loader span::after { content: ''; position: absolute; top: 50%; left: 0; width: calc(var(--loader-size) * .12); height: calc(var(--loader-size) * .12); margin-top: calc(var(--loader-size) * -.06); border-radius: 50%; background: var(--accent-2); }
.loader span:nth-child(1) { animation: orbit-a calc(var(--loader-speed) * 1.8) linear infinite; }
.loader span:nth-child(2) { animation: orbit-b calc(var(--loader-speed) * 2.2) linear infinite; }
.loader span:nth-child(3) { animation: orbit-c calc(var(--loader-speed) * 2.6) linear infinite; }
@keyframes orbit-a { to { rotate: 360deg; } }
@keyframes orbit-b { from { rotate: 120deg; } to { rotate: 480deg; } }
@keyframes orbit-c { from { rotate: 240deg; } to { rotate: 600deg; } }
